<div id="kt_content_container" class="container-xxl py-5"><div class="mb-7"><h1 class="fw-bold text-gray-900 mb-2">Gestión de Usuarios</h1><div class="text-muted fs-6">Crear, modificar roles y activar o inactivar usuarios</div></div><div id="alerta-usuarios"></div><div class="card card-flush"><div class="card-body pt-0"><table class="table align-middle table-row-dashed" id="tabla_usuarios"><thead><tr><th>Nombre</th><th>Correo de acceso</th><th>Rol</th><th>Estatus</th><th>Acciones</th></tr></thead><tbody></tbody></table></div></div></div><div class="modal fade" id="modal_usuario_admin" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="form_usuario_admin"><div class="modal-header"><h2>Editar usuario</h2><button type="button" class="btn btn-icon" data-bs-dismiss="modal"><i class="ki-outline ki-cross fs-1"></i></button></div><div class="modal-body"><input type="hidden" name="id_usuario" id="admin_id_usuario"><label class="form-label">Nombre</label><input class="form-control mb-3" name="nombre" id="admin_nombre" required><label class="form-label">Correo</label><input class="form-control mb-3" type="email" name="email" id="admin_email" required><label class="form-label">Rol</label><select class="form-select mb-3" name="id_rol" id="admin_rol" required></select><label class="form-label">Estatus</label><select class="form-select mb-3" name="estatus" id="admin_estatus"><option value="1">Activo</option><option value="0">Inactivo</option></select><label class="form-label">Nueva contraseña</label><input class="form-control" type="password" name="password" minlength="6" placeholder="Opcional"></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div></form></div></div></div>
<script>
(function(){const alerta=document.getElementById('alerta-usuarios'),tabla=$('#tabla_usuarios');let usuarios=[];Promise.all([fetch('actions/03.read_usuarios.php').then(r=>r.json()),fetch('actions/01.read_roles.php').then(r=>r.json())]).then(([u,r])=>{usuarios=u.data||[];$('#admin_rol').html((r.data||[]).map(x=>'<option value="'+x.id_rol+'">'+x.nombre+'</option>').join(''));tabla.DataTable({data:usuarios,columns:[{data:'nombre',title:'Usuario'},{data:'email',title:'Correo'},{data:'id_rol',title:'Rol',render:x=>x==1?'super_admin':x==2?'admin':'cliente'},{data:'estatus',title:'Estatus',render:x=>x==1?'<span class="badge badge-light-success">Activo</span>':'<span class="badge badge-light-danger">Inactivo</span>'},{data:'id_usuario',title:'Acciones',orderable:false,render:x=>'<button class="btn btn-sm btn-light-primary editar-usuario" data-id="'+x+'">Editar</button>'}],language:{url:'https://cdn.datatables.net/plug-ins/1.13.7/i18n/es-ES.json'}});});tabla.on('click','.editar-usuario',function(){const u=usuarios.find(x=>Number(x.id_usuario)===Number($(this).data('id')));if(!u)return;$('#admin_id_usuario').val(u.id_usuario);$('#admin_nombre').val(u.nombre);$('#admin_email').val(u.email);$('#admin_rol').val(u.id_rol);$('#admin_estatus').val(u.estatus);bootstrap.Modal.getOrCreateInstance(document.getElementById('modal_usuario_admin')).show();});$('#form_usuario_admin').on('submit',function(e){e.preventDefault();fetch('actions/19.update_usuario_admin.php',{method:'POST',body:new FormData(this)}).then(r=>r.json()).then(x=>{alerta.innerHTML='<div class="alert alert-'+(x.success?'success':'danger')+'">'+(x.message||x.error)+'</div>';if(x.success)bootstrap.Modal.getInstance(document.getElementById('modal_usuario_admin')).hide();});});})();
</script>
